export function userPreferenceSettingsPayload(settings: Settings, theme: AppTheme) {
  const preferences: Partial<Settings> = { themePreference: theme };
  for (const key of USER_PREFERENCE_SETTING_KEYS) {
    const value = settings[key];
    if (value !== undefined) (preferences as Record<string, unknown>)[key] = value;
  }
  return preferences;
}

export function userPreferencesFromUser(user?: User | null): Partial<Settings> {
  return user?.preferences && typeof user.preferences === "object" ? (user.preferences as Partial<Settings>) : {};
}

