export function isProjectLead(user: Pick<User, "id"> | null | undefined, project?: Pick<Project, "memberships"> | null) {
  const userId = user?.id;
  if (!userId || !project) return false;
  const membership = (project.memberships || []).find((entry) => entry.userId === userId && String(entry.status || "active") === "active");
  return Boolean(membership?.isLead || /^(project lead|lead|producer|project manager|manager|owner)$/.test(String(membership?.roleLabel || membership?.roleKey || "").trim().toLowerCase()));
}

