export function TemplateStudioPanel({ projects, users }: { projects: Project[]; users: Array<User | UserActivitySummary> }) {
  const seedTemplates: StudioTemplateRecord[] = [
    {
      id: "seed-card",
      type: "card",
      name: "Feature card",
      body: "Goal:\nAcceptance criteria:\nRisks:\nNotes:",
      checklist: "Design reviewed\nImplementation complete\nQA pass",
      defaultPriority: "medium",
      createdAt: new Date().toISOString(),
    },
    {
      id: "seed-report",
      type: "ticket",
      name: "Bug ticket",
      body: "Observed:\nExpected:\nSteps:\nBuild:\nAttachments:",
      checklist: "Triaged\nAssigned\nVerified\nClosed",
      defaultPriority: "high",
      createdAt: new Date().toISOString(),
    },
    {
      id: "seed-build",
      type: "build",
      name: "Release candidate",
      body: "Branch:\nArtifact:\nKnown issues:\nRelease notes:",
      checklist: "Playtest pass\nQA handoff\nRelease notes\nApproval",
      defaultPriority: "urgent",
      createdAt: new Date().toISOString(),
    },
  ];
  const [templates, setTemplates, templateState] = useServerState<StudioTemplateRecord[]>("studio", "templates.workflow", seedTemplates);
  const [form, setForm] = useState({
    type: "card" as StudioTemplateRecord["type"],
    name: "",
    body: "",
    checklist: "",
    defaultPriority: "medium" as StudioTemplateRecord["defaultPriority"],
  });
  function addTemplate() {
    if (!form.name.trim()) return;
    setTemplates(
      [
        {
          id: localId("template"),
          ...form,
          name: form.name.trim(),
          createdAt: new Date().toISOString(),
        },
        ...templates,
      ].slice(0, 120),
    );
    setForm((prev) => ({ ...prev, name: "", body: "", checklist: "" }));
  }
  const counts = templates.reduce<Record<string, number>>(
    (acc, template) => ({
      ...acc,
      [template.type]: (acc[template.type] || 0) + 1,
    }),
    {},
  );
  return (
    <section className="panel template-studio-v122">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Templates</p>
          <h2>Reusable workflow templates</h2>
          <p className="muted tight">Card, ticket, build, meeting, milestone, whiteboard, and Library starters.</p>
        </div>
        <span className="soft-pill">{templates.length} templates</span>
      </div>
      <div className="template-stats-v122">
        {["card", "ticket", "build", "meeting", "milestone", "whiteboard", "library"].map((type) => (
          <span key={type}>
            {levelLabel(type)}
            <strong>{counts[type] || 0}</strong>
          </span>
        ))}
      </div>
      <div className="template-form-v122">
        <div className="field">
          <label>Type</label>
          <ClusterNativeSelect
            value={form.type}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                type: event.target.value as StudioTemplateRecord["type"],
              }))
            }
          >
            <option value="card">Card</option>
            <option value="ticket">Ticket</option>
            <option value="build">Build</option>
            <option value="meeting">Meeting</option>
            <option value="milestone">Milestone</option>
            <option value="whiteboard">Whiteboard</option>
            <option value="library">Library item/folder</option>
          </ClusterNativeSelect>
        </div>
        <div className="field">
          <label>Name</label>
          <ClusterTextInput value={form.name} onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))} placeholder="Template name" />
        </div>
        <div className="field">
          <label>Default priority</label>
          <ClusterNativeSelect
            value={form.defaultPriority}
            onChange={(event) =>
              setForm((prev) => ({
                ...prev,
                defaultPriority: event.target.value as StudioTemplateRecord["defaultPriority"],
              }))
            }
          >
            <option value="none">None</option>
            <option value="low">Low</option>
            <option value="medium">Medium</option>
            <option value="high">High</option>
            <option value="urgent">Urgent</option>
          </ClusterNativeSelect>
        </div>
        <div className="field full">
          <label>Body</label>
          <ClusterTextArea value={form.body} onChange={(event) => setForm((prev) => ({ ...prev, body: event.target.value }))} placeholder="Default body, acceptance criteria, release notes, meeting agenda..." />
        </div>
        <div className="field full">
          <label>Checklist</label>
          <ClusterTextArea value={form.checklist} onChange={(event) => setForm((prev) => ({ ...prev, checklist: event.target.value }))} placeholder="One checklist item per line" />
        </div>
        <ClusterButton type="button" className="" onClick={addTemplate} variant="primary">
          Save template
        </ClusterButton>
      </div>
      <div className="template-list-v122">
        {templates.map((template) => (
          <article key={template.id}>
            <div>
              <strong>{template.name}</strong>
              <span>
                {levelLabel(template.type)} · {template.defaultPriority === "none" ? "No priority" : levelLabel(template.defaultPriority)}
              </span>
              <p>{template.body || "No body."}</p>
            </div>
            <em>{template.checklist.split("\n").filter(Boolean).length} checks</em>
            <ClusterButton type="button" className="" onClick={() => setTemplates(templates.filter((item) => item.id !== template.id))} variant="quiet" size="compact">
              Remove
            </ClusterButton>
          </article>
        ))}
      </div>
      <p className="muted tight">
        Templates are stored on the server and shared across the studio. {projects.length} projects and {users.length} users can use the current catalog.{templateState.saving ? " Saving changes…" : ""}
      </p>
    </section>
  );
}

export function mentionNamesFromText(text: string) {
  return Array.from(text.matchAll(/@([a-z0-9_.-]+)/gi)).map((match) => match[1].toLowerCase());
}

export function reportLifecycleStage(card: TicketCard) {
  if (card.ticketStage) return ({ new: "New / Untriaged", accepted: "Accepted", working: "Working", waiting: "Waiting", review: "Needs review", resolved: "Resolved", rejected: "Rejected" } as Record<string, string>)[card.ticketStage] || "New / Untriaged";
  const text = `${card.listTitle} ${card.labels.join(" ")} ${card.description || ""}`.toLowerCase();
  if (/reopened|reopen/.test(text)) return "Reopened";
  if (/closed|done|resolved|complete|approved|shipped/.test(text) || card.listIsDone) return "Closed";
  if (/review|verify|validation|qa pass/.test(text)) return "Needs review";
  if (/progress|doing|active|assigned/.test(text)) return "In progress";
  if (/triage|backlog|intake/.test(text)) return "Triaged";
  return "Open";
}

export function buildProjectLinkRows(projects: Project[], cards: TicketCard[], timelineEntries: TimelineEntry[]) {
  return projects
    .map((project) => {
      const projectCards = cards.filter((card) => card.projectId === project.id);
      const reports = projectCards.filter((card) => card.labels.some((label) => /report|ticket|bug|qa/i.test(label)) || /report|ticket|bug|qa/i.test(`${card.title} ${card.description || ""}`));
      const roadmap = timelineEntries.filter((entry) => entry.project?.id === project.id);
      const files = project.libraryItems?.length || 0;
      const boards = project.boards.length;
      const whiteboards = project.whiteboards?.length || 0;
      const linkedScore = [boards, whiteboards, files, reports.length, roadmap.length].filter(Boolean).length;
      return {
        project,
        boards,
        whiteboards,
        files,
        reports: reports.length,
        roadmap: roadmap.length,
        linkedScore,
      };
    })
    .sort((a, b) => b.linkedScore - a.linkedScore || a.project.name.localeCompare(b.project.name));
}

export function entityLabel(entity?: string | null) {
  if (entity === "whiteboard") return "Whiteboard";
  if (entity === "project_file") return "File";
  if (entity === "review_asset") return "Review asset";
  if (entity === "review_comment") return "Review note";
  if (!entity) return "Activity";
  return entity.slice(0, 1).toUpperCase() + entity.slice(1).replace(/[_-]/g, " ");
}

export function sensitiveHiddenText(label: string) {
  return `${label} hidden`;
}

export function statusLabel(status?: string | null) {
  switch (status) {
    case "available":
      return "Available";
    case "away":
      return "Away";
    case "focus":
      return "Focus";
    case "offline":
      return "Offline";
    default:
      return "Available";
  }
}

export function priorityIcon(priority: Priority) {
  switch (priority) {
    case "urgent":
      return "!!";
    case "high":
      return "!";
    case "medium":
      return "•";
    case "low":
      return "-";
  }
}

export function toDateInputValue(value?: string | null) {
  if (!value) return "";
  return new Date(value).toISOString().slice(0, 10);
}

