export function studioSlug(value: string, fallback = "custom") {
  return (
    (value || fallback)
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 48) || fallback
  );
}

export function splitCsv(value?: string | null) {
  return unique(
    String(value || "")
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean),
  );
}

export function normalizeRoleId(value: string) {
  return studioSlug(value).replace(/^qa_lead$/, "qa_lead");
}

export function roleLabelFromId(id: string) {
  return id
    .split("_")
    .map((part) => (part ? part[0].toUpperCase() + part.slice(1) : part))
    .join(" ");
}

export function mergeStudioDepartments(input?: StudioDepartmentDefinition[] | null) {
  const byId = new Map<string, StudioDepartmentDefinition>();
  DEFAULT_STUDIO_DEPARTMENTS.forEach((department) => byId.set(department.id, { ...department }));
  (input || []).forEach((department) => {
    const id = studioSlug(department.id || department.label, "department");
    const fallback = byId.get(id);
    const capacityTargetHours = Number(department.capacityTargetHours ?? fallback?.capacityTargetHours ?? 0) || undefined;
    byId.set(id, {
      ...fallback,
      ...department,
      id,
      label: department.label?.trim() || fallback?.label || roleLabelFromId(id),
      defaultTeamName: department.defaultTeamName?.trim() || fallback?.defaultTeamName || "",
      capacityTargetHours,
      permissionTemplateKey: department.permissionTemplateKey || fallback?.permissionTemplateKey || "member",
      toolPermissions: { ...(fallback?.toolPermissions || {}), ...(department.toolPermissions || {}) },
      enabled: department.enabled !== false,
    });
  });
  return Array.from(byId.values());
}

export function mergeStudioRoles(settings?: Pick<Settings, "studioRoleDefinitions" | "studioProjectCreateRolesCsv" | "studioBuildApprovalRolesCsv" | "studioQaApprovalRolesCsv" | "studioAdminRolesCsv" | "studioDefaultWorkspaceRole"> | null) {
  const byId = new Map<string, StudioRoleDefinition>();
  DEFAULT_STUDIO_ROLES.forEach((role) => byId.set(role.id, { ...role }));
  (settings?.studioRoleDefinitions || []).forEach((role) => {
    const id = normalizeRoleId(role.id || role.label);
    const fallback = byId.get(id);
    byId.set(id, {
      ...fallback,
      ...role,
      id,
      label: role.label?.trim() || fallback?.label || roleLabelFromId(id),
      toolPermissions: { ...(fallback?.toolPermissions || {}), ...(role.toolPermissions || {}) },
      enabled: role.enabled !== false,
    });
  });
  [settings?.studioProjectCreateRolesCsv, settings?.studioBuildApprovalRolesCsv, settings?.studioQaApprovalRolesCsv, settings?.studioAdminRolesCsv, settings?.studioDefaultWorkspaceRole].forEach((source) => {
    splitCsv(source).forEach((item) => {
      const id = normalizeRoleId(item);
      if (!byId.has(id)) byId.set(id, { id, label: roleLabelFromId(id), enabled: true });
    });
  });
  return Array.from(byId.values());
}

export function rolesCsvFromIds(ids: string[]) {
  return unique(ids).join(", ");
}

export function enabledStudioDepartmentsFromSettings(settings?: Settings | null) {
  return mergeStudioDepartments(settings?.studioDepartmentDefinitions).filter((department) => department.enabled !== false);
}

export function enabledStudioRolesFromSettings(settings?: Settings | null) {
  return mergeStudioRoles(settings).filter((role) => role.enabled !== false);
}

export function allManageToolPermissions(): ToolPermissions {
  return Object.fromEntries(TOOL_PERMISSION_OPTIONS.map((tool) => [tool.key, "manage"])) as ToolPermissions;
}

export function rolePermissionTemplateOptions() {
  return [
    {
      key: "member",
      label: "Member defaults",
      tools: DEFAULT_MEMBER_TOOL_PERMISSIONS,
    },
    {
      key: "viewer",
      label: "Viewer defaults",
      tools: DEFAULT_VIEWER_TOOL_PERMISSIONS,
    },
    {
      key: "all-manage",
      label: "Full management",
      tools: allManageToolPermissions(),
    },
    ...ROLE_PERMISSION_TEMPLATES.map((template) => ({
      key: template.key,
      label: template.label,
      tools: template.tools,
    })),
  ];
}

export function permissionTemplateTools(templateKey?: string | null) {
  return rolePermissionTemplateOptions().find((item) => item.key === templateKey)?.tools || {};
}

export function departmentPermissionsFromSettings(settings: Settings | null | undefined, departmentId?: string | null): ToolPermissions {
  const department = mergeStudioDepartments(settings?.studioDepartmentDefinitions).find((item) => item.id === departmentId);
  if (!department || department.enabled === false) return { ...DEFAULT_MEMBER_TOOL_PERMISSIONS };
  return {
    ...permissionTemplateTools(department.permissionTemplateKey || "member"),
    ...(department.toolPermissions || {}),
  };
}

export function rolePermissionsFromSettings(settings: Settings | null | undefined, roleId?: string | null): ToolPermissions | null {
  const normalizedRoleId = normalizeRoleId(roleId || "");
  if (!normalizedRoleId) return null;
  const role = mergeStudioRoles(settings).find((item) => item.id === normalizedRoleId);
  if (!role || role.enabled === false) return null;
  if (["owner", "admin"].includes(role.id)) return allManageToolPermissions();
  const templateKey = role.permissionTemplateKey || (role.id === "viewer" ? "viewer" : role.id === "member" ? "member" : "");
  const departmentDefaults = departmentPermissionsFromSettings(settings, role.departmentId);
  const template = rolePermissionTemplateOptions().find((item) => item.key === templateKey);
  return {
    ...departmentDefaults,
    ...(template?.tools || {}),
    ...(role.toolPermissions || {}),
  };
}

export function studioDepartmentLabelById(settings: Settings | null | undefined, id?: string | null) {
  return enabledStudioDepartmentsFromSettings(settings).find((department) => department.id === id)?.label || "";
}

