export function deriveNeedsAttention({ projects = [], dueCards = [], timelineEntries = [], buildEntries = [], users = [], librarySummary = null, timeSummary = null, activeEntry = null, activity = [], lastSeenAt, projectWorkflows = {} }: { projects?: Project[]; dueCards?: UpcomingPayload["dueCards"]; timelineEntries?: TimelineEntry[]; buildEntries?: Array<TimelineEntry | TimelineItem>; users?: UserActivitySummary[]; librarySummary?: LibrarySummary | null; timeSummary?: TimeSummary | null; activeEntry?: TimeEntry | null; activity?: ActivityEvent[]; lastSeenAt?: string | null; projectWorkflows?: ProjectWorkflowAttentionState }) {
  const yesterday = Date.now() - 24 * 60 * 60 * 1000;
  const staleCutoff = Date.now() - 14 * 24 * 60 * 60 * 1000;
  const items: AttentionItem[] = [];
  dueCards
    .filter((card) => isPast(card.dueDate))
    .forEach((card) => {
      items.push(
        makeAttentionItem({
          id: `overdue-card-${card.id}`,
          source: "timeline",
          severity: card.priority === "urgent" ? "critical" : card.priority === "high" ? "high" : "medium",
          title: card.title,
          detail: `${card.project.name} · due ${formatDueDate(card.dueDate)} · ${card.board.name}`,
          projectId: card.project.id,
          projectName: card.project.name,
          createdAt: card.dueDate,
          actionLabel: "Open timeline",
          target: "timeline",
        }),
      );
    });
  timelineEntries
    .filter((entry) => isPast(entry.startsAt) && !isToday(entry.startsAt))
    .slice(0, 12)
    .forEach((entry) => {
      const text = `${entry.type} ${entry.title} ${entry.description || ""}`.toLowerCase();
      if (/done|complete|shipped|closed|archive/.test(text)) return;
      items.push(
        makeAttentionItem({
          id: `overdue-timeline-${entry.source}-${entry.id}`,
          source: "timeline",
          severity: /release|milestone|deadline|launch/.test(text) ? "high" : "medium",
          title: entry.title,
          detail: `${entry.project?.name || "Studio"} · ${compactDateTime(entry.startsAt)} should be reviewed`,
          projectId: entry.project?.id || null,
          projectName: entry.project?.name || null,
          createdAt: entry.startsAt,
          actionLabel: "Review timeline",
          target: "timeline",
        }),
      );
    });
  projects
    .filter((project) => !project.archived && normalizeProjectStatus(project.status) === "active" && projectLatestTimestamp(project) > 0 && projectLatestTimestamp(project) < staleCutoff)
    .forEach((project) => {
      items.push(
        makeAttentionItem({
          id: `stale-project-${project.id}`,
          source: "project",
          severity: "medium",
          title: `${project.name} is stale`,
          detail: `No visible project update since ${compactDateTime(new Date(projectLatestTimestamp(project)).toISOString())}`,
          projectId: project.id,
          projectName: project.name,
          createdAt: project.updatedAt || new Date(projectLatestTimestamp(project)).toISOString(),
          actionLabel: "Open project",
          target: "projects",
        }),
      );
    });
  projects
    .filter((project) => !project.archived && !projectAssignedIds(project).length)
    .forEach((project) => {
      items.push(
        makeAttentionItem({
          id: `missing-lead-${project.id}`,
          source: "project",
          severity: "high",
          title: `${project.name} has no lead`,
          detail: "Assign a project lead.",
          projectId: project.id,
          projectName: project.name,
          createdAt: project.updatedAt,
          actionLabel: "Assign lead",
          target: "projects",
        }),
      );
    });
  buildEntries
    .filter((entry) => /block|blocked|hold|risk|fail|failed|waiting|approval/i.test(`${entry.title} ${entry.description || ""} ${entry.type || ""}`))
    .forEach((entry) => {
      items.push(
        makeAttentionItem({
          id: `blocked-build-${entry.id}`,
          source: "build",
          severity: "high",
          title: entry.title,
          detail: `${entry.project?.name || "Studio"} · build needs unblock/review`,
          projectId: entry.project?.id || null,
          projectName: entry.project?.name || null,
          createdAt: entry.startsAt,
          actionLabel: "Open builds",
          target: "builds",
        }),
      );
    });
  const reviewDocs = Number(librarySummary?.byStatus?.["needs-review"] || 0) + Number(librarySummary?.byStatus?.["in-review"] || 0) + Number(librarySummary?.byStatus?.["needs-update"] || 0);
  if (reviewDocs > 0) {
    items.push(
      makeAttentionItem({
        id: "library-review-docs",
        source: "library",
        severity: reviewDocs > 5 ? "high" : "medium",
        title: `${reviewDocs} library item${reviewDocs === 1 ? "" : "s"} need review`,
        detail: "Specs, briefs, or decisions are waiting for approval/update.",
        actionLabel: "Open library",
        target: "library",
      }),
    );
  }
  const externalProjects = projects.filter(isExternalProject);
  const externalNeeds = externalProjects.filter((project) => projectHealth(project).tone !== "good" || projectSetupGaps(project).length > 0);
  externalNeeds.forEach((project) => {
    items.push(
      makeAttentionItem({
        id: `external-review-${project.id}`,
        source: "external",
        severity: "medium",
        title: `${project.name} external delivery needs review`,
        detail: projectSetupGaps(project).slice(0, 3).join(" · ") || "Check external deliverable status.",
        projectId: project.id,
        projectName: project.name,
        createdAt: project.updatedAt,
        actionLabel: "Open external project",
        target: "projects",
      }),
    );
  });
  users
    .filter((user) => profileWorkloadTone(user.counts?.assignedCards || 0, user.capacityHours) === "danger")
    .forEach((user) => {
      items.push(
        makeAttentionItem({
          id: `over-capacity-${user.id}`,
          source: "team",
          severity: "high",
          title: `${displayUserName(user)} is over capacity`,
          detail: `${user.counts?.assignedCards || 0} assigned cards${user.capacityHours != null ? ` · ${user.capacityHours}h/week capacity` : " · capacity unset"}`,
          createdAt: user.updatedAt,
          actionLabel: "Open team",
          target: "people",
        }),
      );
    });
  if ((timeSummary?.runningCount || 0) > 1) {
    items.push(
      makeAttentionItem({
        id: "running-time-review",
        source: "time",
        severity: "medium",
        title: `${timeSummary?.runningCount || 0} running time entries`,
        detail: "Review active clocks and correct any missed clock-outs.",
        actionLabel: "Open time",
        target: "scheduler",
      }),
    );
  }
  if (activeEntry) {
    const minutes = Math.max(activeEntry.computedDurationMinutes || 0, Math.round((Date.now() - new Date(activeEntry.startedAt).getTime()) / 60000));
    if (minutes > 10 * 60)
      items.push(
        makeAttentionItem({
          id: `long-shift-${activeEntry.id}`,
          source: "time",
          severity: "high",
          title: "Long active shift",
          detail: `${minutesToHuman(minutes)} running since ${compactDateTime(activeEntry.startedAt)}. Check for missed clock-out.`,
          createdAt: activeEntry.startedAt,
          actionLabel: "Review clock",
          target: "scheduler",
        }),
      );
    shiftRuleWarnings(projectWorkflows.shiftRules || readShiftRules(), activeEntry, [], []).forEach((warning) =>
      items.push(
        makeAttentionItem({
          id: `shift-rule-${warning.id}`,
          source: "time",
          severity: warning.tone,
          title: warning.title,
          detail: warning.detail,
          createdAt: activeEntry.startedAt,
          actionLabel: "Open time rules",
          target: "scheduler",
        }),
      ),
    );
  }
  const correctionRequests = (projectWorkflows.correctionRequests || []).map(normalizeCorrectionRequest);
  const pendingCorrections = correctionRequests.filter((request) => ["open", "reviewing", "approved"].includes(request.status));
  if (pendingCorrections.length > 0) {
    items.push(
      makeAttentionItem({
        id: "pending-time-corrections",
        source: "time",
        severity: pendingCorrections.some((request) => request.issueType === "forgot-clock-out" || request.issueType === "duplicate-entry") ? "high" : "medium",
        title: `${pendingCorrections.length} time correction${pendingCorrections.length === 1 ? "" : "s"} waiting`,
        detail: pendingCorrections
          .slice(0, 3)
          .map((request) => `${request.userName}: ${timeCorrectionIssueLabel(request.issueType)}`)
          .join(" · "),
        createdAt: pendingCorrections[0]?.updatedAt || pendingCorrections[0]?.createdAt,
        actionLabel: "Review corrections",
        target: "scheduler",
      }),
    );
  }
  const missedBreaks = (projectWorkflows.breakLedger || []).filter((item) => item.status === "missed" && new Date(item.createdAt).getTime() > Date.now() - 7 * 24 * 60 * 60 * 1000);
  if (missedBreaks.length > 0) {
    items.push(
      makeAttentionItem({
        id: "missed-break-review",
        source: "time",
        severity: missedBreaks.length > 3 ? "high" : "medium",
        title: `${missedBreaks.length} missed break${missedBreaks.length === 1 ? "" : "s"} logged`,
        detail: "Review break compliance before timesheets are approved.",
        createdAt: missedBreaks[0]?.createdAt,
        actionLabel: "Open time rules",
        target: "scheduler",
      }),
    );
  }
  const qaPlans = (projectWorkflows.qaPlans || []).map(normalizeTestPlan);
  const qaBlockers = qaPlans.filter((plan) => ["failed", "blocked"].includes(plan.status));
  if (qaBlockers.length > 0) {
    items.push(
      makeAttentionItem({
        id: "qa-plan-blockers",
        source: "ticket",
        severity: qaBlockers.some((plan) => plan.status === "blocked") ? "high" : "medium",
        title: `${qaBlockers.length} QA test plan${qaBlockers.length === 1 ? "" : "s"} failing`,
        detail: qaBlockers
          .slice(0, 3)
          .map((plan) => `${plan.title}: ${levelLabel(plan.status)}`)
          .join(" · "),
        createdAt: qaBlockers[0]?.updatedAt,
        actionLabel: "Open QA",
        target: "tickets",
      }),
    );
  }
  const since = lastSeenAt ? new Date(lastSeenAt).getTime() : yesterday;
  activity
    .filter((event) => new Date(event.createdAt).getTime() >= since && /approval|triage|blocked|urgent|critical|failed|rejected|changes/i.test(`${event.title} ${event.message || ""} ${event.type}`))
    .slice(0, 8)
    .forEach((event) => {
      const source: AttentionItem["source"] = /approval|approved|rejected|changes/i.test(`${event.title} ${event.message || ""}`) ? "approval" : /report|qa|ticket|bug/i.test(`${event.entityType} ${event.title}`) ? "ticket" : "activity";
      items.push(
        makeAttentionItem({
          id: `activity-attention-${event.id}`,
          source,
          severity: /urgent|critical|blocked|failed/i.test(`${event.title} ${event.message || ""}`) ? "high" : "medium",
          title: event.title,
          detail: event.message || `${entityLabel(event.entityType)} ${event.type}`,
          projectId: event.project?.id || null,
          projectName: event.project?.name || null,
          createdAt: event.createdAt,
          actionLabel: source === "ticket" ? "Open Tickets" : source === "approval" ? "Open Inbox" : "Open Activity",
          target: source === "ticket" ? "tickets" : source === "approval" ? "inbox" : "activity",
        }),
      );
    });
  items.push(...workflowAttentionItems(projects, {
    links: projectWorkflows.links,
    recurring: projectWorkflows.recurring,
    watchers: projectWorkflows.watchers,
  }));
  items.push(...closeoutAttentionItems(projects, projectWorkflows.closeouts, projectWorkflows.portalRules));
  items.push(...attachmentAttentionItems(projects, projectWorkflows.attachments || []));
  items.push(...maintenanceAttentionItems(projects, projectWorkflows.attachments || []));
  return dedupeBy(items, (item) => item.id).sort((a, b) => attentionSeverityRank(b.severity) - attentionSeverityRank(a.severity) || new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
}

export function buildCommandBrief({ projects = [], dueCards = [], timelineEntries = [], buildEntries = [], users = [], librarySummary = null, timeSummary = null, activeEntry = null, activity = [], lastSeenAt, projectWorkflows = {} }: { projects?: Project[]; dueCards?: UpcomingPayload["dueCards"]; timelineEntries?: TimelineEntry[]; buildEntries?: Array<TimelineEntry | TimelineItem>; users?: UserActivitySummary[]; librarySummary?: LibrarySummary | null; timeSummary?: TimeSummary | null; activeEntry?: TimeEntry | null; activity?: ActivityEvent[]; lastSeenAt?: string | null; projectWorkflows?: ProjectWorkflowAttentionState }): CommandBrief {
  const items = deriveNeedsAttention({
    projects,
    dueCards,
    timelineEntries,
    buildEntries,
    users,
    librarySummary,
    timeSummary,
    activeEntry,
    activity,
    lastSeenAt,
    projectWorkflows,
  });
  const since = lastSeenAt ? new Date(lastSeenAt).getTime() : Date.now() - 24 * 60 * 60 * 1000;
  const reportsNeedingTriage = items.filter((item) => item.source === "ticket").length + dueCards.filter((card) => /report|ticket|qa|bug/i.test(`${card.title} ${card.board.name} ${card.list.title}`) && isPast(card.dueDate)).length;
  return {
    generatedAt: new Date().toISOString(),
    clockedIn: Math.max(timeSummary?.runningCount || 0, activeEntry ? 1 : 0),
    overdue: dueCards.filter((card) => isPast(card.dueDate)).length + timelineEntries.filter((entry) => isPast(entry.startsAt) && !isToday(entry.startsAt)).length,
    changedSinceYesterday: activity.filter((event) => new Date(event.createdAt).getTime() >= since).length,
    reportsNeedingTriage,
    blockedBuilds: items.filter((item) => item.source === "build").length,
    approvalsWaiting: items.filter((item) => item.source === "approval").length + Number(librarySummary?.byStatus?.["in-review"] || 0),
    todayMilestones: timelineEntries.filter((entry) => isToday(entry.startsAt) && /milestone|release|build|playtest|deadline|review|launch/i.test(`${entry.type} ${entry.title}`)).length,
    externalUpdates: projects.filter(isExternalProject).length + activity.filter((event) => event.project && isExternalProject(event.project as Project) && new Date(event.createdAt).getTime() >= since).length,
    topItems: items.slice(0, 6),
  };
}

export function isOverdue(value?: string | null) {
  if (!value) return false;
  const due = new Date(value);
  due.setHours(23, 59, 59, 999);
  return due.getTime() < Date.now();
}

export function monthStart(value: Date) {
  return new Date(value.getFullYear(), value.getMonth(), 1);
}

export function addMonths(value: Date, amount: number) {
  return new Date(value.getFullYear(), value.getMonth() + amount, 1);
}

export function sameDate(a: Date, b: Date) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

export function dateKey(value: Date | string) {
  const date = typeof value === "string" ? new Date(value) : value;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).toISOString().slice(0, 10);
}

export const appearanceKeys = new Set<keyof Settings>(["fontFamily", "accentColor", "secondaryAccentColor", "dangerColor", "cornerRadius", "glassStrength", "backgroundStyle", "backgroundBaseStyle", "backgroundPattern", "backgroundPatternIntensity", "backgroundPatternScale", "cardStyle", "surfaceStyle", "motionLevel", "interfaceDensity", "sidebarStyle", "sidebarSurface", "taskbarSurface", "taskbarLayout", "sidebarLayout", "sidebarItemStyle", "surfaceDepth", "surfaceTexture", "surfaceTextureIntensity", "iconSize", "panelBorders", "scrollbarStyle", "projectTabStyle", "userTaskbarLabels", "userLargeClickTargets", "userReducedContrast", "userMotionPreference", "userContrastPreference", "userTransparencyPreference", "userFocusIndicator", "userTextScale", "userLargeClickTargets", "userStatusPalette", "userShowHelpText"]);


export function snapshotChangeCount(current: unknown, previous: unknown) {
  if (!current || !previous || typeof current !== "object" || typeof previous !== "object") return JSON.stringify(current) === JSON.stringify(previous) ? 0 : 1;
  const currentRecord = current as Record<string, unknown>;
  const previousRecord = previous as Record<string, unknown>;
  return [...new Set([...Object.keys(currentRecord), ...Object.keys(previousRecord)])].filter((key) => JSON.stringify(currentRecord[key]) !== JSON.stringify(previousRecord[key])).length;
}

export function snapshotDiffEntries(current: unknown, previous: unknown) {
  const currentRecord = current && typeof current === "object" ? (current as Record<string, unknown>) : { value: current };
  const previousRecord = previous && typeof previous === "object" ? (previous as Record<string, unknown>) : { value: previous };
  return [...new Set([...Object.keys(currentRecord), ...Object.keys(previousRecord)])]
    .filter((key) => JSON.stringify(currentRecord[key]) !== JSON.stringify(previousRecord[key]))
    .slice(0, 20)
    .map((key) => ({
      key,
      before: previousRecord[key],
      after: currentRecord[key],
    }));
}

export function snapshotValuePreview(value: unknown) {
  if (value === undefined) return "Not set";
  if (value === null) return "None";
  if (typeof value === "string") return value.length > 120 ? `${value.slice(0, 117)}...` : value;
  const serialized = JSON.stringify(value);
  return serialized.length > 120 ? `${serialized.slice(0, 117)}...` : serialized;
}

export function libraryTypeLabel(type?: string | null) {
  if (type === "decision") return "Decision";
  if (type === "spec") return "Spec";
  if (type === "link") return "Link";
  if (type === "meeting") return "Meeting";
  if (type === "reference") return "Reference";
  if (type === "folder") return "Folder";
  return "Note";
}
